import { describe, expect, it } from "vitest"

import { agentsDescription } from "./list-workspaces.js"

describe("agentsDescription", () => {
  it("skips every line of a multi-line comment", () => {
    const markdown = [
      "# Handbook",
      "",
      "<!--",
      "Generated by a tool.",
      "Do not edit this block by hand.",
      "-->",
      "",
      "The platform teams share this handbook.",
    ].join("\n")
    expect(agentsDescription(markdown)).toBe(
      "The platform teams share this handbook.",
    )
  })

  it("skips a comment inside a paragraph", () => {
    expect(agentsDescription("Start <!-- one\ntwo --> end.")).toBe("Start end.")
  })

  it("reads only the first 16 KiB", () => {
    const markdown = `${"x ".repeat(9_000)}\n\nlater paragraph`
    expect(agentsDescription(markdown)?.length).toBeLessThanOrEqual(300)
    expect(agentsDescription(`${" ".repeat(17_000)}hidden`)).toBeNull()
  })
})
